14	/// A test runner that can start a gateway and execute GraphQL queries against it.
15	pub struct TestRunner {
16	    http_client: reqwest::Client,
17	    config: TestConfig,
18	    gateway_handle: Option<duct::Handle>,
19	    gateway_listen_address: SocketAddr,
20	    gateway_endpoint: Url,
